const rewindHistoryCheckpointBeforeTurn = `-- name: RewindHistoryCheckpointBeforeTurn :one
WITH owner_session AS MATERIALIZED (
  SELECT session.id
  FROM bot_sessions session
  WHERE session.team_id = public.memoh_current_team_id()
    AND session.id = $1
    AND session.bot_id = $2
  FOR UPDATE
), replaced AS MATERIALIZED (
  SELECT MIN(m.turn_position)::bigint AS turn_position,
    MIN(m.turn_message_seq)::bigint AS turn_message_seq
  FROM bot_visible_history_messages m
  JOIN owner_session owner ON owner.id = m.session_id
  WHERE m.team_id = public.memoh_current_team_id()
    AND m.turn_id = $3
    AND (m.metadata->>'trigger_mode' IS NULL OR m.metadata->>'trigger_mode' != 'passive_sync')
)
SELECT COALESCE((
  SELECT public.memoh_rewind_history_checkpoint(owner.id, replaced.turn_position, replaced.turn_message_seq)
  FROM replaced
  WHERE replaced.turn_position IS NOT NULL
), false)::boolean AS rewound
FROM owner_session owner
`

type RewindHistoryCheckpointBeforeTurnParams struct {
	SessionID pgtype.UUID `json:"session_id"`
	BotID     pgtype.UUID `json:"bot_id"`
	TurnID    pgtype.UUID `json:"turn_id"`
}

// An edit or retry that compacts before its first step commits rewinds the
// session as SelectBoundHistoryTurnReplacement will when that step replaces
// the turn, so its fold builds on the checkpoint the replacement keeps. It
// reports whether it rewound.
func (q *Queries) RewindHistoryCheckpointBeforeTurn(ctx context.Context, arg RewindHistoryCheckpointBeforeTurnParams) (bool, error) {
	row := q.db.QueryRow(ctx, rewindHistoryCheckpointBeforeTurn, arg.SessionID, arg.BotID, arg.TurnID)
	var rewound bool
	err := row.Scan(&rewound)
	return rewound, err
}

const setHistoryCheckpoint = `-- name: SetHistoryCheckpoint :execrows
UPDATE bot_sessions
SET history_checkpoint_id = $1::uuid
WHERE team_id = public.memoh_current_team_id()
  AND id = $2
  AND history_checkpoint_id IS NOT DISTINCT FROM $3::uuid
`

type SetHistoryCheckpointParams struct {
	CheckpointID         pgtype.UUID `json:"checkpoint_id"`
	SessionID            pgtype.UUID `json:"session_id"`
	ExpectedCheckpointID pgtype.UUID `json:"expected_checkpoint_id"`
}

// Moves the session's active checkpoint, only from the one the caller read.
func (q *Queries) SetHistoryCheckpoint(ctx context.Context, arg SetHistoryCheckpointParams) (int64, error) {
	result, err := q.db.Exec(ctx, setHistoryCheckpoint, arg.CheckpointID, arg.SessionID, arg.ExpectedCheckpointID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
